package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;import com.insight.quantlife.*;import java.io.*;import java.util.regex.*;

/** Real Feishu code-heavy sample plus synthetic fence round trips; emulator only. */
public class CodeReaderTest extends ReaderSaveTest {
 String url="";
 @Override public void onCreate(Bundle b){url=b==null?"":b.getString("docUrl","");super.onCreate(b);}
 String file(String name)throws Exception{return new String(java.nio.file.Files.readAllBytes(new File(getTargetContext().getFilesDir(),"qa/"+name).toPath()),"UTF-8").replace("\uFEFF","");}
 JSONObject doc(String note,String title){try{return new JSONObject().put("id","code-reader-"+System.nanoTime()).put("type","learning").put("date","2026-10-27").put("title",title).put("note",note).put("durationMinutes",0).put("tags",new JSONArray());}catch(Exception e){throw new RuntimeException(e);}}
 void reader(JSONObject r)throws Exception{h.js("RecordEditor.open("+r.toString()+",null,'learning',true)");until("!!document.querySelector('#doc-flow .doc-code-card')");Thread.sleep(400);}
 void scan()throws Exception{
  h.js("document.querySelector('#doc-flow').style.transition='none';while(!document.querySelector('#doc-prev').disabled)document.querySelector('#doc-prev').click()");
  int pages=Integer.parseInt(h.js("+document.querySelector('#doc-page').textContent.split('/')[1]"));check(pages>0&&pages<100,"Bounded code cards produce reasonable page count: "+pages);
  check(h.js("(()=>{const f=document.querySelector('#doc-flow'),v=document.querySelector('#doc-viewport').getBoundingClientRect();return [...f.querySelectorAll('.doc-code-card')].every(c=>c.getBoundingClientRect().height<=v.height+1&&c.getBoundingClientRect().width<=v.width+1&&c.querySelector('pre').clientHeight>0)})()").equals("true"),"Every code card fits within a reading page, including landscape");
  for(int i=0;i<pages;i++){check(h.js("(()=>{const v=document.querySelector('#doc-viewport').getBoundingClientRect();return [...document.querySelectorAll('#doc-flow h1,#doc-flow p,#doc-flow .doc-code-card')].some(e=>[...e.getClientRects()].some(r=>r.width>0&&r.height>0&&r.right>v.left+1&&r.left<v.right-1&&r.bottom>v.top&&r.top<v.bottom))})()").equals("true"),"No empty page "+(i+1));if(i<pages-1)click("#doc-next");}
 }
 @Override public void onStart(){Bundle result=new Bundle();try{
  if(!Build.HARDWARE.matches("ranchu|goldfish"))throw new Exception("Requires disposable emulator");h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");
  if(url.isEmpty())throw new Exception("Pass authorized Feishu URL using docUrl");
  JSONObject live=(JSONObject)h.call("feishuRead",new JSONObject().put("url",url));String note=live.getString("note");check(live.getString("title").equals("LangChain案例演示"),"Read actual third Feishu document");
  String xml=new JSONObject(file("third-cli.json")).getJSONObject("data").getJSONObject("document").getString("content");Matcher m=Pattern.compile("<pre[^>]*lang=\"([^\"]*)\"[^>]*><code>([\\s\\S]*?)</code></pre>").matcher(xml);JSONArray originals=new JSONArray(),languages=new JSONArray();while(m.find()){languages.put(m.group(1));String raw=m.group(2).replaceAll("<br\\s*/?>","\n").replaceAll("</?(?:em|strong|b|i)>","").replace("&lt;","<").replace("&gt;",">").replace("&quot;","\"").replace("&#39;","'").replace("&amp;","&");originals.put(raw);}
  check(originals.length()==21,"Independent document fetch has all 21 original code blocks");reader(doc(note,live.getString("title")).put("date",live.getString("documentCreatedDate")));h.js("window.originalCodes="+originals.toString()+";window.originalLanguages="+languages.toString());
  check(h.js("document.querySelectorAll('#doc-flow .doc-code-card').length===originalCodes.length").equals("true"),"All 21 fenced blocks render as exactly 21 intact cards");
  for(int i=0;i<21;i++){check(h.js("document.querySelectorAll('#doc-flow .doc-code-card code')["+i+"].textContent===originalCodes["+i+"]").equals("true"),"Code "+(i+1)+" retains blank lines, indentation, punctuation and comments");}
  check(h.js("[...document.querySelectorAll('#doc-flow .doc-code-card')].every((c,i)=>c.dataset.codeLanguage===originalLanguages[i])").equals("true"),"Imported Python/Markdown language labels retained");scan();h.js("while(!document.querySelector('#doc-prev').disabled)document.querySelector('#doc-prev').click()");Thread.sleep(250);h.screenshot("code-reader-real.png");
  click("#doc-flow [data-code-open]");check(h.js("!!document.querySelector('#doc-code-viewer') && document.querySelector('#doc-code-viewer code').textContent===originalCodes[0]").equals("true"),"Full-screen viewer shows exact original code");click("[data-code-wrap]");check(h.js("document.querySelector('[data-code-wrap]').getAttribute('aria-pressed')==='true' && document.querySelector('#doc-code-viewer pre').scrollWidth<=document.querySelector('#doc-code-viewer pre').clientWidth+1").equals("true"),"Full-screen soft wrap fits long lines without modifying source");h.screenshot("code-fullscreen-real.png");click("[data-code-copy]");until("document.querySelector('.doc-code-status').textContent==='代码已复制'");h.js("RecordEditor.back()");until("!document.querySelector('#doc-code-viewer')");check(h.js("document.querySelector('#editor').open").equals("true"),"System back closes code only, preserving reader");
  click("#doc-mode");check(h.js("DocumentRich.serialize(document.querySelector('#doc-body'))==="+JSONObject.quote(note)).equals("true"),"Real note read/edit round trip preserves entire imported source");
  click("#doc-body [data-code-open]");String replacement=originals.getString(0)+"\n\n# 本机编辑验证\nprint('``` literal')  \n";h.js("document.querySelector('#doc-code-input').value="+JSONObject.quote(replacement));click("[data-code-save]");until("!document.querySelector('#doc-code-viewer')");check(h.js("document.querySelector('#doc-body .doc-code-card code').textContent==="+JSONObject.quote(replacement)).equals("true"),"Dedicated code editor preserves inserted whitespace and literal backticks");
  h.js("window.expectedCodeEdit=(()=>{let first=true;return ChatMarkdown.blocks("+JSONObject.quote(note)+").map(b=>b.type==='code'&&first?(first=false,ChatMarkdown.fenced("+JSONObject.quote(replacement)+",b.language)+b.suffix):b.source).join('')})()");check(h.js("DocumentRich.serialize(document.querySelector('#doc-body'))===expectedCodeEdit").equals("true"),"Editing one code block preserves all prose, other code blocks and source separators");click("#doc-undo");check(h.js("DocumentRich.serialize(document.querySelector('#doc-body'))==="+JSONObject.quote(note)).equals("true"),"Code edit can be undone without rewriting original source");click("#doc-redo");check(h.js("DocumentRich.serialize(document.querySelector('#doc-body'))===expectedCodeEdit").equals("true"),"Code redo restores only intended change");click("#doc-mode");check(h.js("document.querySelector('#doc-flow .doc-code-card code').textContent==="+JSONObject.quote(replacement)).equals("true"),"Edited code safely renders again using a long enough fence");close();
  String sample="前文。\n\n````markdown\n```python\n\n# 不是标题\n![literal](zhishi-media:"+String.join("",java.util.Collections.nCopies(64,"a"))+")\n<script>window.bad=true</script>\n```\n````\n\n后文。";JSONObject synthetic=doc(sample,"混合代码安全回归 "+System.nanoTime());reader(synthetic);check(h.js("document.querySelectorAll('#doc-flow .doc-code-card').length===1&&!document.querySelector('#doc-flow img')&&!window.bad").equals("true"),"Nested fences, fake image tokens and HTML stay literal code");click("#doc-mode");check(h.js("DocumentRich.serialize(document.querySelector('#doc-body'))==="+JSONObject.quote(sample)).equals("true"),"Nested code literal survives editing round trip byte-for-byte");click("#doc-save");until("document.querySelector('#doc-mode').textContent==='编辑'&&!document.querySelector('#doc-save').disabled");check(record(synthetic.getString("id")).getString("note").equals(sample),"Native save never includes card controls or alters code source");close();reader(record(synthetic.getString("id")));check(h.js("document.querySelectorAll('#doc-flow .doc-code-card').length===1&&!document.querySelector('#doc-flow img')").equals("true"),"Saved code note reloads with same intact code container");close();h.call("applyRecordAction",new JSONObject().put("kind","delete").put("recordId",synthetic.getString("id")).put("expectedVersion",record(synthetic.getString("id")).getLong("updatedAt")));
  FeishuImport.clear(getTargetContext(),live.getString("ticket"));result.putString("stream","PASS CodeReaderTest: "+passed+" checks\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable ex){try{if(h!=null)h.screenshot("code-reader-failure.png");}catch(Exception ignored){}result.putString("stream","FAIL CodeReaderTest after "+passed+": "+ex+"\n"+android.util.Log.getStackTraceString(ex));finish(Activity.RESULT_CANCELED,result);}}
}
